#!/usr/bin/env bash
# Rewrites supabase/migrations/*.sql so they create their objects inside a
# dedicated schema pair instead of `public` / `private`.
#
# Used when the Supabase instance already hosts another application in the
# default schemas. The generated files are the ones applied with psql; the
# migrations in supabase/migrations/ stay the single source of truth.
#
#   supabase/scripts/to-schema.sh waclonegem build/sql-waclonegem
#
# Renames applied, in order:
#   public.<object>   -> <schema>.<object>
#   private.<object>  -> <schema>_private.<object>
#   set search_path   -> <schema>, <schema>_private, auth, extensions
#   on schema public  -> on schema <schema>
#   on schema private -> on schema <schema>_private
#
# The role named `public` in GRANT/REVOKE statements is left untouched.

set -euo pipefail

schema="${1:?usage: to-schema.sh <schema> <outdir>}"
outdir="${2:?usage: to-schema.sh <schema> <outdir>}"
private="${schema}_private"

root="$(cd "$(dirname "$0")/../.." && pwd)"
src="$root/supabase/migrations"
mkdir -p "$outdir"

first=1
for file in "$src"/*.sql; do
  base="$(basename "$file")"
  target="$outdir/$base"
  {
    if [ "$first" = "1" ]; then
      cat <<SQL
-- Generated by supabase/scripts/to-schema.sh from $base.
-- Objects live in schema "$schema" (was public) and "$private" (was private).
create schema if not exists "$schema";
create schema if not exists "$private";
grant usage on schema "$schema" to anon, authenticated, service_role;
grant usage on schema "$private" to service_role;
SQL
      first=0
    fi
    sed -E \
      -e "s/\bpublic\./$schema./g" \
      -e "s/\bprivate\./$private./g" \
      -e "s/^(set search_path = ).*/\1$schema, $private, auth, extensions/" \
      -e "s/on schema public/on schema $schema/g" \
      -e "s/in schema public/in schema $schema/g" \
      -e "s/on schema private/on schema $private/g" \
      -e 's/create extension if not exists "citext";/create extension if not exists "citext" with schema extensions;/' \
      "$file"
  } > "$target"
done

# Supabase ships default privileges that hand `public` tables to the API roles;
# a freshly created schema has none, so PostgREST and the Edge Functions would
# be locked out ("permission denied for table profiles"). Mirror those grants
# here, last in file order so the tables already exist.
cat > "$outdir/zz-role-grants.sql" <<SQL
-- Generated by supabase/scripts/to-schema.sh.
grant usage on schema "$schema" to anon, authenticated, service_role;
grant usage on schema "$private" to service_role;
grant all on all tables in schema "$schema" to service_role;
grant all on all sequences in schema "$schema" to service_role;
grant all on all routines in schema "$schema" to service_role;
grant all on all tables in schema "$private" to service_role;
grant all on all sequences in schema "$private" to service_role;
grant all on all routines in schema "$private" to service_role;
alter default privileges in schema "$schema" grant all on tables to service_role;
alter default privileges in schema "$schema" grant all on sequences to service_role;
alter default privileges in schema "$schema" grant all on routines to service_role;

-- auth.users is shared with the other application on this instance, so a global
-- invite-only trigger there would break that app's own sign-ups. Registration
-- stays invite-only on our side: the register function is the only path into
-- the app and it requires a valid code, and finalize_registration refuses any
-- user without a redeemed invite.
drop trigger if exists enforce_invite_only on auth.users;
SQL

echo "wrote $(ls "$outdir" | wc -l) file(s) to $outdir"
